import 'dart:io';
import 'dart:typed_data';

import 'package:inventrix/features/auditor_exports/domain/repositories/export_ports.dart';
import 'package:path/path.dart' as p;

/// Keeps exports in one folder, [directory]. Names are plain file names
/// generated by the app; anything with a path separator is refused.
final class FileExportStore implements ExportFileStore {
  /// Creates the store. [directory] returns the exports folder.
  const FileExportStore(this.directory);

  /// Gives the exports folder (created on first write).
  final Future<String> Function() directory;

  String _checked(String fileName) {
    if (fileName != p.basename(fileName) || fileName.startsWith('.')) {
      throw ArgumentError.value(fileName, 'fileName', 'must be a plain file name');
    }
    return fileName;
  }

  @override
  Future<String> write(String fileName, Uint8List bytes) async {
    final folder = Directory(await directory());
    await folder.create(recursive: true);
    final target = File(p.join(folder.path, _checked(fileName)));
    final partial = File('${target.path}.part');
    await partial.writeAsBytes(bytes, flush: true);
    await partial.rename(target.path);
    return target.path;
  }

  @override
  Future<Uint8List?> read(String fileName) async {
    final file = File(await resolve(fileName));
    return await file.exists() ? file.readAsBytes() : null;
  }

  @override
  Future<String> resolve(String fileName) async =>
      p.join(await directory(), _checked(fileName));

  @override
  Future<void> delete(String fileName) async {
    final file = File(await resolve(fileName));
    if (await file.exists()) {
      await file.delete();
    }
  }
}
